"""Append measured outcomes to CHANGES_forecast.md; never edit old results."""
import argparse,json,sys
from pathlib import Path
import pandas as pd
ROOT=Path(__file__).resolve().parents[1]
def md_table(headers,rows):
    return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(str(x) for x in row)+' |' for row in rows])
def number(v,d=4):return 'NA' if pd.isna(v) else f'{v:.{d}f}'
def report(out):
    selection=json.loads((out/'selection.json').read_text());summary=json.loads((out/'analysis_summary.json').read_text());selected=selection['selected_method'];m=pd.read_csv(out/'test_metrics.csv');val=pd.read_csv(out/'validation_metrics.csv');ci=pd.read_csv(out/'test_bootstrap_ci.csv');delta=pd.read_csv(out/'test_vs_mean_paired_bootstrap_ci.csv');coverage=pd.read_csv(out/'test_interval_coverage.csv');dm=pd.read_csv(out/'test_dm_vs_mean.csv');fit=pd.read_csv(out/'fit_diagnostics.csv');tests=json.loads((out/'tests.json').read_text());comparison=pd.read_csv(out/'selected_comparison.csv');baseline=json.loads((out/'baseline_reproduction.json').read_text());preserved=json.loads((out/'preservation_verified.json').read_text());gate=selection['validation_deployment_gate_passed']
    log=ROOT/'CHANGES_forecast.md';existing=log.read_text(encoding='utf-8');marker=f'## Final measured results — {out.name}';assert marker not in existing,'This run is already recorded; do not overwrite or append duplicate results.'
    bits=[marker,'\nProduction forecaster **unchanged**. Validation selected **`'+selected+'`**. All-horizon deployment gate passed: **'+str(gate)+'**. '+('Additional deployment/cold-start integration was not undertaken; the candidate remains experimental.' if gate else 'The predeclared validation requirements were not satisfied; test outcomes do not reverse that decision.'),'\nNo earlier result artifact or dataset was modified: '+str(preserved['preserved_files'])+' preserved files verified. Source snapshot, environment versions and exact split/model rules are in the new output directory and `forecast_audit/PROTOCOL.md`. Existing paper/router work is untouched.']
    bits+=['\n### Validation-only choice',md_table(['Model','Horizon','Validation MAE','Validation RMSE'],[[r.method,r.horizon,number(r.mae,2),number(r.rmse,2)] for r in val[(val.scope=='pooled')&val.seed.isin(['deterministic','ensemble'])&val.method.isin(['original','historical_mean',selected])].itertuples()]),'One configuration was chosen globally by equal-horizon normalized validation MAE+RMSE; no seed, platform-specific model, test winner or CI/p-value was selected. The five-seed arithmetic ensemble defines each boosting candidate. All candidate and individual-seed metrics remain in the CSVs.']
    bits+=['\n### Identical-test-window comparisons',md_table(['Model','Horizon','Windows','Forecast pairs','Unique targets','MAE','RMSE','sMAPE (%)','MASE'],[[r.method,r.horizon,r.n_windows,r.n_forecast_instances,r.n_unique_targets,number(r.mae,2),number(r.rmse,2),number(r.smape,2),number(r.mase)] for r in comparison.itertuples()])]
    changes=[]
    for h in [7,15,30]:
        new=comparison[(comparison.method==selected)&(comparison.horizon==h)].iloc[0]
        for reference in ['original','historical_mean']:
            old=comparison[(comparison.method==reference)&(comparison.horizon==h)].iloc[0]
            for k in ['mae','rmse','smape','mase']:
                changes.append([reference,h,k,number(new[k]-old[k]),number((new[k]/old[k]-1)*100,2)+'%' if old[k] else 'NA'])
    bits.append(md_table(['Reference','Horizon','Metric','Selected absolute change','Selected relative change'],changes))
    bits+=['Errors are computed on forecast instances (origin,lead), with duplicates across overlapping windows explicitly counted. Whole files/platforms are retained; the longer Zomato gig series contributes more pooled forecasts. Per-file/platform tables and equal-series macro metrics expose that imbalance. These are synthetic, previously examined histories, not an unseen external cohort.']
    bits+=['Cross-horizon pooled errors are composition-confounded: the long gig series contributes 28/108 seven-day origins, 26/86 fifteen-day origins and 21/31 thirty-day origins. A lower pooled thirty-day error is not evidence that longer-horizon prediction is easier. Compare models within identical horizons and inspect equal-series/per-platform results.']
    selectedci=ci[(ci.scope=='pooled')&ci.method.isin(['original','historical_mean',selected])]
    bits+=['\n### Bootstrap uncertainty',md_table(['Model','Horizon','Metric','Estimate','95% lower','95% upper','Clusters'],[[r.method,r.horizon,r.metric,number(r.estimate),number(r.ci95_lower),number(r.ci95_upper),r.clusters] for r in selectedci.itertuples()]),'5000 whole-platform bootstrap draws: five fixed seeds x 1000 draws. All series/origins/leads in a sampled platform stay together; no IID resampling of overlapping target errors. Per-platform CIs resample entire series within that platform. With only five platforms and two/three series per platform, these intervals are coarse, conditional on the fitted models and synthetic corpus, and do not establish external significance.']
    diff=delta[(delta.scope=='pooled')&(delta.method==selected)]
    bits+=['Paired selected-minus-historical-mean intervals (negative error delta favors selected):',md_table(['Horizon','Metric','Delta','95% lower','95% upper'],[[r.horizon,r.metric,number(r.estimate_delta),number(r.ci95_lower),number(r.ci95_upper)] for r in diff.itertuples()])]
    bits+=['Interpretation: the selected model\'s pooled MAE-difference intervals exclude zero at all horizons, but RMSE-difference intervals include zero at all horizons. The thirty-day point RMSE is worse than historical mean. These conditional bootstrap findings do not establish an external or all-metric forecasting win.']
    d=dm[(dm.scope=='pooled_common')&dm.method.isin(['original',selected])]
    bits+=['\n### Diebold–Mariano vs historical mean',md_table(['Model','Horizon','Loss','Common origins','HAC lag','DM statistic','Raw p','BH p','Status'],[[r.method,r.horizon,r.loss,r.n_origins,r.hac_lag,number(r.statistic),number(r.p_raw),number(r.p_bh),r.status] for r in d.itertuples()]),f'{summary["dm_estimable"]} comparisons were estimable and {summary["dm_unavailable"]} were explicitly unavailable across all scope/model/loss combinations. DM averages losses over the horizon at each origin, uses Newey-West/Bartlett HAC and HLN finite-sample correction, and never concatenates independent series. Only common dates with fixed series composition enter pooled/platform tests. Horizon-15/30 common panels are especially short; insufficient origins are NA, not p=1 or p=0. Full per-file/platform/common-panel results are in `test_dm_vs_mean.csv`. BH p-values cover all estimable comparisons; small-sample/dependence assumptions remain limitations.']
    cover=coverage[(coverage.scope=='pooled')&coverage.method.isin(['original','historical_mean',selected])]
    bits+=['\n### Frozen conformal intervals',md_table(['Model','Horizon','Nominal coverage','Observed coverage','Mean width (Rs)','Mean interval score','Calibration scores'],[[r.method,r.horizon,number(r.nominal_coverage,2),number(r.empirical_coverage),number(r.mean_width,2),number(r.mean_interval_score,2),r.calibration_scores] for r in cover.itertuples()]),'Selection uses rows 28:60; calibration uses only 60:90 and nonoverlapping full-horizon target blocks; test starts at 90. Finite-sample rank-adjusted absolute residual quantiles are frozen before test. Scaling uses only the preceding 30 training incomes. Coverage is empirical marginal coverage over forecast instances, not simultaneous path coverage. Serial dependence, rolling refits, cross-series heterogeneity and pooled calibration prevent an ordinary IID conformal coverage guarantee. Per-platform and lead coverage are reported, including undercoverage; intervals are not tuned to test coverage.']
    platform_cover=coverage[(coverage.scope=='platform')&(coverage.method==selected)&(coverage.nominal_coverage==.9)]
    bits+=['Selected-model nominal 90% coverage by platform:',md_table(['Platform','Horizon','Observed coverage','Mean width (Rs)'],[[r.group,r.horizon,number(r.empirical_coverage),number(r.mean_width,2)] for r in platform_cover.itertuples()]),'Blinkit undercoverage and wide intervals show that acceptable pooled coverage does not imply conditional usefulness. Both 90% and 95% levels remain reported; no level/model was chosen to hide coverage failure. Intervals are implemented in the experiment scripts; the application response schema remains unchanged.']
    bits+=['\n### Failures, tests and remaining limits',f'- New test suite: **{tests["total"]} tests, {tests["passed"]} passed, {tests["failed"]} failures, {tests["errors"]} errors**. Full output is retained. Leakage/split/seed checks and artifact freezing checks are included.',f'- Across all stages, **{int(fit.fallbacks.sum())} fit exceptions/nonfinite-output fallbacks**, **{int(fit.nonconverged.sum())} nonconverged finite fits**, and **{int(fit.warnings.sum())} fits with warnings** were retained. Diagnostics identify stage/model/origin/seed and error; no failed case was deleted. Finite nonconverged fits remain part of the named model result. Caches store only source/prefix/config/seed-keyed predictions and diagnostics.', '- sMAPE uses 200*absolute error/(abs actual + abs predicted), 0/0=0. Seasonal MASE uses only training-prefix lag-7 absolute differences; zero denominators are NA with `mase_n` reported, never silently replaced by a favorable scale.', '- Horizon 30 has one complete test origin in each 120-day series after independent calibration. The longer 180-day series supplies the remaining rolling origins. No extra test data or fabricated independent windows were generated.', '- All configurations and five seeds were fixed before validation/test scoring. If a different configuration happens to have a better test score, it remains unselected. No claim of statistical significance follows solely from lower pooled error. These are library baselines and a small lag-feature experiment, not a novel model or proof of practical financial benefit.', '- Production inference, package manifests, router contracts and previous metrics are unchanged. No test result was used to authorize a production replacement.']
    bits+=['\n### Files and reproduction','`forecast_audit/run.py`: model fitting and exclusive staged outputs. `analyze.py`: metrics, bootstrap, DM and interval coverage. `test_forecast.py`: automated checks. `preserve.py`: baseline replay and preservation verification. `PROTOCOL.md`: fixed design. `requirements.txt`/`environment.lock.txt`: isolated dependency versions. `report.py`: append-only measured changelog. All CSV/JSON/log results live in `'+str(out.relative_to(ROOT)).replace('\\','/')+'`.', 'Important CSVs: `validation_metrics.csv`, `validation_selection_scores.csv`, `test_metrics.csv`, `test_equal_series_macro_metrics.csv`, `test_seed_variability.csv`, `test_bootstrap_ci.csv`, `test_vs_mean_paired_bootstrap_ci.csv`, `test_dm_vs_mean.csv`, `conformal_quantiles.csv`, `test_interval_coverage.csv`, `test_interval_coverage_by_lead.csv`, `fit_diagnostics.csv`, and `selected_comparison.csv`. Prediction CSVs retain the complete audit trail. Prior reports remain historical, unchanged.']
    bits.append('''```powershell
# Use a NEW results directory: outputs refuse overwrites.
python -m venv forecast_audit/.venv
& forecast_audit/.venv/Scripts/python.exe -m pip install -r forecast_audit/environment.lock.txt
python forecast_audit/preserve.py --out forecast_audit/results_reproduction
& forecast_audit/.venv/Scripts/python.exe forecast_audit/run.py select --out forecast_audit/results_reproduction
& forecast_audit/.venv/Scripts/python.exe forecast_audit/run.py calibrate --out forecast_audit/results_reproduction
& forecast_audit/.venv/Scripts/python.exe forecast_audit/run.py test --out forecast_audit/results_reproduction
& forecast_audit/.venv/Scripts/python.exe forecast_audit/analyze.py --out forecast_audit/results_reproduction
& forecast_audit/.venv/Scripts/python.exe forecast_audit/check_results.py --out forecast_audit/results_reproduction
python forecast_audit/preserve.py --out forecast_audit/results_reproduction --verify
```''')
    with log.open('a',encoding='utf-8') as f:f.write('\n\n'+'\n\n'.join(bits)+'\n')
    print('Appended measured final results to CHANGES_forecast.md')
if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--out',type=Path,required=True);a=p.parse_args();report(a.out.resolve())
